//! Lens Flare fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){
 let mut cases=vec![];
 for (w,h) in [(1,7),(7,1),(6,4),(18,10)] {for lens in 0u32..4 {for center in [[None,None],[Some(0.5),Some(0.5)],[Some(1.23456789012345),Some(-2.0)],[None,Some(2.125)]] {for (brightness,blend,size,ghosts) in [(0.0,0.0,10.0,0.0),(100.0,100.0,100.0,3.0),(300.0,25.0,400.0,8.0),(100.0,0.0,75.0,3.5)] {for color in [[1.0,0.9,0.75,1.0],[-1.0,2.0,0.5,0.0]] {
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let input:Vec<[f32;4]>=rgba.chunks_exact(4).map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2] as f32/255.0)*a,a]}).collect();
  let mut image=Image{w,h,px:input.iter().flatten().copied().collect()};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="lens_flare").unwrap().instance();
  effect.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(center[0].unwrap_or(f64::NAN),center[1].unwrap_or(f64::NAN)))));
  effect.params.insert("lens_type".into(),Param::new(ParamValue::Choice(lens)));
  effect.params.insert("color".into(),Param::new(ParamValue::Color(color)));
  for(name,value)in [("brightness",brightness),("blend",blend),("size",size),("ghosts",ghosts)]{effect.params.insert(name.into(),Param::new(ParamValue::Float(value)));}
  let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.0,seconds:0.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  cases.push(json!({"parameters":{"center":center,"lensType":lens,"brightness":brightness,"blend":blend,"size":size,"ghosts":ghosts,"color":color},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}}}
 let mut media=vec![];
 for lens in 0u32..4 {for tick in [0u64,250000,500000] {
  let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,if i%16<8&&i/16<12 {128}else{0}]}).collect();
  let mut frames=vec![];
  for index in 0..(1000000-tick).div_ceil(100000) {
   let local=(tick+index*100000).min(500000);let progress=local as f64/500000.0;
   let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
   let mut image=Image{w:16,h:16,px};
   let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="lens_flare").unwrap().instance();
   effect.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(8.0-progress*6.75,8.0-progress*5.875))));
   for(name,value)in [("brightness",progress*300.0),("blend",progress*25.0),("size",10.0+progress*390.0),("ghosts",progress*8.0)]{effect.params.insert(name.into(),Param::new(ParamValue::Float(value)));}
   effect.params.insert("lens_type".into(),Param::new(ParamValue::Choice(lens)));
   effect.params.insert("color".into(),Param::new(ParamValue::Color([progress as f32,(1.0-progress)as f32,(progress*0.5)as f32,progress as f32])));
   let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.0,seconds:local as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
   apply(&mut image,&effect,&cx);frames.push(image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());
  }
  media.push(json!({"lensType":lens,"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
 }
 }
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));
}
